-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "元素生物"
L["rm.era.shaman.elemental.Description"] = "元素，10 级起（大部分天赋点在元素）；综合 Icy Veins 和 Wowhead。地震术用于打断以及收掉即将死亡的目标。移动时：烈焰震击，否则冰霜震击。单刷且目标处于近战范围时：目标生命值高于 30% 时使用地震术，然后近战。三个或更多敌人时：处于近战时使用火焰新星图腾和熔岩图腾，以及闪电链。元素掌握或节能施法期间使用闪电链，否则使用闪电箭。提醒：闪电之盾、团队副本之外的石化武器、灼热图腾或熔岩图腾、法力之泉图腾或治疗之泉图腾、闪电链就绪时使用元素掌握、低于 30% 时使用自然迅捷和治疗波、拉怪后的治疗。驱散、净化术和降级施法由你自己掌控。"
L["rm.era.shaman.elemental.simulator.Name"] = "元素，闪电链冷却完毕即用（模拟器）"
L["rm.era.shaman.elemental.simulator.Description"] = "模拟器 的元素列表，是推荐的元素内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。即使只有一个目标，闪电链也冷却完毕即用，元素掌握生效时使用地震术，否则使用闪电箭。比推荐的内置循环更快，但耗蓝多得多；打断、图腾和提醒相同。"
L["rm.era.shaman.enhancement.Name"] = "增强"
L["rm.era.shaman.enhancement.Description"] = "1–60 级，也适用于专家模式和自给自足服务器，以及天赋点没有明显集中的所有萨满祭司；综合 Icy Veins、Wowhead 和 模拟器。从远处用闪电箭拉怪；用地震术打断。团队副本中只使用风暴打击和冰霜震击（减益效果栏位有限）。有三个或更多敌人与你交战时，使用火焰新星图腾和熔岩图腾。然后是风暴打击，在风暴打击的减益效果期间或收尾时使用地震术，烈焰震击能完整持续时使用烈焰震击，法力值还有一半时使用地震术，目标不在攻击范围内时使用闪电箭。提醒：单刷时石化武器、地下城中风怒武器，闪电之盾，大地之力图腾，灼热图腾，风怒图腾或风之优雅图腾，法力之泉图腾或治疗之泉图腾，拉怪后和紧急时的治疗。石爪图腾、地缚图腾、图腾轮换和种族技能列为关闭状态；驱散、净化术和清除类图腾由你自己掌控。"
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "增强，烈焰震击优先（Warcraft Tavern）"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "Warcraft Tavern 的增强，是推荐的增强内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。一学会就使用风怒武器，风暴打击，在任何直接伤害的震击之前先上烈焰震击，然后在你的仇恨较低时使用地震术，组队时仇恨升高后改用冰霜震击；对怪群使用熔岩图腾和闪电链。图腾和提醒与推荐的内置循环相同。"
L["rm.era.shaman.restoration.Name"] = "恢复"
L["rm.era.shaman.restoration.Description"] = "恢复，10 级起（大部分天赋点在恢复）；综合 Icy Veins 和 Wowhead。对你的友方目标：自然迅捷期间使用治疗波，低于 30% 时使用自然迅捷，低于 40% 时使用次级治疗波，消毒术或祛病术，你附近有三名队友低于 85% 时使用治疗链，否则低于 90% 时使用治疗波。对它所交战的敌人：地震术打断，对怪群使用闪电链，烈焰震击，远程使用闪电箭，近战。提醒：单刷时闪电之盾和石化武器、组队时法力之潮图腾、法力之泉图腾、大地之力图腾、灼热图腾。治疗谁、降级施法以及战栗图腾或清除类图腾由你自己掌控；在坦克身上保持治疗之道列为关闭状态。"
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "恢复，治疗链优先（Warcraft Tavern）"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "Warcraft Tavern 的恢复，是推荐的恢复内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。任何人低于 90% 时都用治疗链治疗，即将死亡的人用次级治疗波；治疗波仅用于拥有治疗之道、被指派治疗坦克的治疗者（列为关闭状态）。驱除、对敌人的伤害和图腾提醒与推荐的内置循环相同。"
L["rm.forever.shaman.elemental.Name"] = "元素生物"
L["rm.forever.shaman.elemental.Description"] = "当元素是你的主要天赋树且已点出 21 点（熔岩爆裂所在层）后的远程元素，依据 Icy Veins（在此之前，由增强内置循环执行所有指南都推荐的近战混合打法）。以闪电箭拉怪（怪群时用闪电链），移动时只施放瞬发法术，三个或更多敌人时使用火焰新星和闪电链，保持烈焰震击，熔岩爆裂冷却完毕即用，若学会风暴打击则使用风暴打击和地震术，组队时节能施法触发则使用火焰新星，然后是闪电箭。提醒：护盾、武器灌注、灼热图腾或熔岩图腾、队伍图腾、元素掌握、打断。在永久服上生命值和法力值对插件隐藏，因此治疗自己和停下来回复法力值由你自己决定。由你自己掌控：地缚图腾放风筝、冰霜震击、净化术和其他图腾。"
L["rm.forever.shaman.enhancement.Name"] = "增强（Icy Veins）"
L["rm.forever.shaman.enhancement.Description"] = "增强近战，适用于 1 至 60 级，也是学会熔岩爆裂或法力之潮图腾之前所有萨满祭司的默认循环。从远处用闪电箭拉怪，然后风暴打击冷却完毕即用，漩涡武器叠满五层时施放瞬发闪电箭，三个或更多敌人时使用火焰新星（需已放下火焰图腾）和烈焰震击，在风暴打击减益效果期间使用地震术，组队时使用烈焰震击，以及地震术冷却完毕即用；目标不在攻击范围内时用闪电箭填补空档。在永久服上生命值和法力值对插件隐藏，因此治疗自己和停下来回复法力值由你自己决定（Wowhead 内置循环则改为节省法力）。提醒：武器灌注（风怒武器，否则火舌武器，再否则石化武器）、水之护盾或闪电之盾、地震术打断、灼热图腾或熔岩图腾、队伍图腾、先知之怒、石爪图腾。由你自己掌控：图腾预设、冰霜震击、净化术和其他图腾。"
L["rm.forever.shaman.enhancement.wowhead.Name"] = "增强，节省法力（Wowhead）"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "Wowhead 和 Mobalytics 的节省法力增强：主要靠自动攻击输出，仅在强化风暴打击的法力回复效果不在时使用风暴打击，循环中不使用地震术（震击术用于拉怪和打断），组队或面对怪群时使用灼热图腾，并在冷却完毕时使用火焰新星。武器灌注、护盾和打断提醒与 Icy Veins 内置循环相同。如果你法力值不够用，请选择它而不是那个内置循环。它是推荐的增强内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.forever.shaman.restoration.Name"] = "恢复"
L["rm.forever.shaman.restoration.Description"] = "当恢复是你的主要天赋树且已点出 16 点（法力之潮图腾所在层）后的治疗，依据 Icy Veins。友方目标时：使用自然迅捷后的瞬发治疗波，消毒术和祛病术，对没有激流的目标使用激流，组队时使用治疗链，治疗波。通过选中目标来决定治疗谁；在永久服上生命值和法力值对插件隐藏，因此何时使用自然迅捷和次级治疗波由你自己决定。目标为敌对且无人需要治疗时：怪群使用火焰新星和闪电链，若学会风暴打击则使用风暴打击和地震术，对精英和首领使用烈焰震击，闪电箭，然后近战。提醒：水之护盾、地震术打断、法力之潮图腾和队伍增益图腾。由你自己掌控：降级施法、其他图腾、净化术和幽魂之狼。"
L["rm.mop.shaman.elemental.Name"] = "推荐"
L["rm.mop.shaman.elemental.Description"] = "推荐元素专精从 10 级起使用，在元素专精中选用。Wowhead 的顺序：以闪电箭开场（有怒火释放时用熔岩爆裂），有怒火释放时使用元素释放，对能存活较久的目标在烈焰震击缺失或即将结束时施放烈焰震击，在烈焰震击上使用熔岩爆裂（每次熔岩奔腾触发时也使用），元素冲击，闪电之盾达到六层充能且烈焰震击还剩 6 秒时使用大地震击，两个敌人时使用闪电链，闪电箭。四个或更多敌人攻击你时：近战时使用熔岩图腾、免费的熔岩爆裂、升腾期间使用熔岩弹射、闪电链。移动时只显示瞬发法术。提醒：闪电之盾、火舌武器、灼热图腾、对精英和首领使用火元素图腾、元素掌握、熔岩爆裂后使用升腾、先祖迅捷、组队时使用风暴之鞭图腾和嗜血、风剪、为法力使用雷霆风暴、生命值低时使用萨满之怒和星界转移。地震术和土元素图腾已列出但关闭。由你自己掌控：灵魂行者的恩赐、对额外目标施放烈焰震击以及站位。"
L["rm.mop.shaman.enhancement.Name"] = "推荐"
L["rm.mop.shaman.enhancement.Description"] = "推荐增强专精从 10 级起使用，在增强专精中选用。Wowhead 的顺序：冲向目标时使用元素释放，然后有怒火释放时使用元素释放，漩涡武器达到五层时使用元素冲击和闪电箭（或在下次挥击还有一秒以上时于三层穿插施放），升腾期间使用风暴轰击，风暴打击（26 级前为根源打击），熔岩猛击，火焰释放期间使用烈焰震击，元素释放，大地震击。两个或更多敌人攻击你时：用闪电链代替闪电箭，用熔岩猛击扩散烈焰震击，四个起使用火焰新星，六个起使用熔岩图腾。提醒：闪电之盾、主手风怒武器和副手火舌武器、灼热图腾、火元素图腾、野性狼魂、风暴打击后使用升腾、元素掌握、先祖迅捷、组队时使用风暴之鞭图腾和嗜血、风剪、生命值低时使用萨满之怒和星界转移。土元素图腾已列出但关闭。"
L["rm.mop.shaman.enhancement.icyveins.Name"] = "熔岩猛击优先（Icy Veins）"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "默认关闭；切换条件与推荐的增强内置循环相同，因此要使用它请启用它并禁用那个。Icy Veins 的顺序：风暴打击，然后在消耗漩涡武器之前使用熔岩猛击，五层时，或从三层起能在下次挥击前完成时使用闪电箭，元素释放然后烈焰震击，大地震击。四个或更多敌人时用熔岩猛击扩散烈焰震击并使用火焰新星；对怪群用闪电链代替闪电箭。战斗中萨满之怒冷却完毕即建议使用；其他提醒与推荐的内置循环相同。"
L["rm.mop.shaman.enhancement.simulator.Name"] = "每层都穿插施放（模拟器）"
L["rm.mop.shaman.enhancement.simulator.Description"] = "默认关闭；切换条件与推荐的增强内置循环相同，因此要使用它请启用它并禁用那个。模拟器为能在挥击间隙安排施法的玩家提供的列表：只要施法能在下一次主手挥击前完成，无论漩涡武器有几层，都使用闪电箭、元素冲击或闪电链，烈焰震击缺失时也使用元素释放，大地震击仅在少于两层时使用。提醒与推荐的内置循环相同。"
L["rm.mop.shaman.restoration.Name"] = "推荐"
L["rm.mop.shaman.restoration.Description"] = "推荐恢复专精从 10 级起使用，在恢复专精中选用。治疗你的友方目标（Rotation Master 无法选择治疗谁）：先祖迅捷期间使用强效治疗波，低于 35% 时使用治疗之涌，有魔法或诅咒效果时使用净化灵魂，附近有三名盟友受伤时先元素释放再治疗之雨，激流，队伍受到伤害时使用治疗链，低于 60% 时使用强效治疗波，低于 90% 时使用治疗波。目标可攻击时改为造成伤害（烈焰震击、熔岩爆裂、元素冲击、闪电箭）。提醒：水之护盾、大地生命武器、对你的焦点目标施放大地之盾、有人受伤时使用治疗之泉图腾、法力之潮图腾、队伍受到重创时使用治疗之潮图腾、元素掌握或先祖指引、对生命值低的目标使用先祖迅捷、移动时使用灵魂行者的恩赐、嗜血、风剪。升腾和灵魂链接图腾已列出但关闭：在你的团队分配时使用它们。"
L["rm.mop.shaman.restoration.hekili.Name"] = "生命值阶梯（Hekili）"
L["rm.mop.shaman.restoration.hekili.Description"] = "默认关闭；切换条件与推荐的恢复内置循环相同，因此要使用它请启用它并禁用那个。Hekili 的列表会在你的目标身上保持大地之盾和激流，治疗之泉图腾和治疗之雨一消失就补上，然后按 40 码内队伍的平均生命值进行治疗：低于 80% 时使用治疗链，目标低于 70% 时使用治疗波，低于 60% 时使用强效治疗波，低于 40% 时使用治疗之涌，治疗之潮图腾、先祖指引和法力之潮图腾也在同一阶梯上。可攻击的目标会获得伤害技能以及大地震击。"
L["rm.mop.shaman.unspecialized.Name"] = "无专精"
L["rm.mop.shaman.unspecialized.Description"] = "适用于 1 至 9 级，以及尚未选择专精的萨满祭司；选择专精后由各专精内置循环接管。从远处用闪电箭拉怪，独自一人且生命值低时使用治疗之涌，根源打击，大地震击，不在近战范围时使用闪电箭。保持闪电之盾。"
L["rm.retail.shaman.elemental.Name"] = "暴雪战斗辅助"
L["rm.retail.shaman.elemental.Description"] = "推荐至暗之夜的元素专精使用。在战斗中，游戏现在会对插件隐藏烈焰震击、你的增益效果、漩涡、冷却时间和生命值，因此它会显示暴雪自己的战斗辅助建议（一键循环），并在你施法或没有选中敌人时停止。提醒它未包含的内容：战斗中的升腾、火元素或风暴元素以及自然迅捷、移动中使用灵魂行者的恩赐、拉怪间隙的闪电之盾和天怒（暴雪的建议会维持你的武器和护盾灌注）、对可打断的施法使用风剪（只在游戏允许读取该施法的场合亮起）、战斗中一就绪就使用的星界转移（生命值在正式服中是隐藏的，因此何时使用由你自己决定）。"
L["rm.retail.shaman.elemental.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.shaman.elemental.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft 的施放顺序需要读取烈焰震击、元素宗师和风暴守护者，而至暗之夜会在战斗中隐藏它们；漩涡在正式服中是隐藏的，所以消耗技能按其消耗施放，而不是在漩涡接近满值时施放。拉怪前使用风暴守护者和熔岩爆裂。面对三个或更多交战中的敌人时：风暴守护者，先祖迅捷，烈焰震击，风暴守护者生效时使用闪电链，元素冲击，地震术，熔岩奔腾触发时使用熔岩爆裂，狂风怒号，闪电链。否则：风暴守护者，先祖迅捷，元素宗师之外在剩余最后 30% 时刷新烈焰震击和流电炽焰，使用熔岩爆裂触发元素宗师，元素宗师期间使用狂风怒号和风暴守护者强化的闪电箭，元素宗师期间使用元素冲击或大地震击，流电炽焰，狂风怒号，移动中使用烈焰震击或冰霜震击，只要负担得起就使用元素冲击或大地震击，闪电箭。提醒：风暴守护者用掉后使用升腾、火元素或风暴元素、灵魂行者的恩赐，以及通用提醒。"
L["rm.retail.shaman.enhancement.Name"] = "暴雪战斗辅助"
L["rm.retail.shaman.enhancement.Description"] = "推荐至暗之夜的增强专精使用。显示暴雪的战斗辅助建议（它会消耗漩涡武器、维持烈焰震击，并处理涌动图腾和裂地术），并在你施法或没有选中敌人时停止。提醒它未包含的内容：战斗中的升腾、毁灭之风和野性狼魂、拉怪间隙的闪电之盾和天怒（暴雪的建议会维持风怒武器）、风剪、星界转移。"
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "风暴使者参考（SimulationCraft）"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "仅供参考，默认关闭：SimulationCraft 的风暴使者列表（Icy Veins 和 Wowhead 的看法一致）需要读取烈焰震击、毁灭闪电、鞭笞烈焰和冷却计时，而至暗之夜会在战斗中隐藏它们。面对三个或更多交战中的敌人时：为获得增益效果使用毁灭闪电，漩涡武器达到 10 层时使用狂风怒号，达到 9 层时使用闪电链，毁灭闪电，熔岩猛击，裂地术。然后漩涡武器达到 9 层时使用始源风暴，烈焰震击缺失时使用流电炽焰或烈焰震击，裂地术，为获得增益效果使用毁灭闪电，为鞭笞烈焰使用熔岩猛击，风切，达到 10 层时使用狂风怒号或闪电箭（流电炽焰或毁灭闪电即将就绪时为 8 层），两层充能时使用风暴打击，熔岩猛击，风暴打击，流电炽焰，毁灭闪电，达到 5 层时使用闪电箭，烈焰震击。提醒：毁灭之风、毁灭之风之外使用升腾、野性狼魂，以及通用提醒。"
L["rm.retail.shaman.enhancement.totemic.Name"] = "图腾祭司参考（SimulationCraft）"
L["rm.retail.shaman.enhancement.totemic.Description"] = "仅供参考，默认关闭：SimulationCraft 的图腾祭司列表需要读取烈焰震击、灼热之手、飞旋之火、毁灭闪电和毁灭之风，而至暗之夜会在战斗中隐藏它们。面对三个或更多交战中的敌人时：毁灭闪电，漩涡武器达到 5 层时使用闪电链。然后烈焰震击缺失时使用流电炽焰或烈焰震击，涌动图腾，裂地术，有灼热之手或飞旋之火时使用熔岩猛击，为获得增益效果使用毁灭闪电，达到 10 层时使用始源风暴，风切，毁灭之风期间使用毁灭闪电和风暴打击，达到 5 层时使用闪电箭，毁灭闪电，熔岩猛击，风暴打击，流电炽焰，烈焰震击。提醒与风暴使者参考循环相同。"
L["rm.retail.shaman.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.shaman.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是萨满祭司的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有萨满祭司内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "至暗之夜的恢复专精，仅供参考：暴雪的战斗辅助不涵盖治疗者，游戏在战斗中会隐藏所有人的生命值，而 Rotation Master 选择的是法术而不是目标，因此它会针对你当前的目标按就绪情况排列你的治疗技能，决定治疗谁则交给你。友方目标：治疗之泉图腾，生命释放，在队伍中使用治疗之雨，涌动图腾，激流，在队伍中使用治疗链，治疗波。敌人：烈焰震击缺失时使用烈焰震击，熔岩爆裂，闪电箭。提醒：拉怪间隙的水之护盾、对友方目标使用大地之盾和天怒；战斗中的自然迅捷；组队战斗中的治疗之潮图腾和灵魂链接图腾；风剪；星界转移。"
L["rm.sod.shaman.elemental.Name"] = "元素（探索赛季）"
L["rm.sod.shaman.elemental.Description"] = "探索赛季的元素，10 级起（大部分天赋点在元素）；综合 模拟器 第 6 阶段、Wowhead 和 Icy Veins。用地震术打断。移动时：烈焰震击，闪电之盾达到八层充能时使用地震术，能量涌动触发时使用熔岩爆裂或闪电链。三个或更多敌人时：烈焰震击、闪电链、火焰新星、熔岩爆裂、八层充能时使用地震术、熔岩图腾。然后能量涌动触发时使用熔岩爆裂，保持烈焰震击，你的烈焰震击持续期间使用熔岩爆裂，八层充能时使用地震术，两个敌人时使用闪电链，闪电箭。提醒：为燃烧使用火舌武器、闪电之盾、对自己施放大地之盾、头狼之魂、野性狼魂、萨满之怒、元素掌握、图腾。饰品、图腾投射、驱散和净化术由你自己掌控。"
L["rm.sod.shaman.enhancement.Name"] = "增强（探索赛季）"
L["rm.sod.shaman.enhancement.Description"] = "探索赛季，1–60 级，符文在你铭刻后即会使用，双持或双手武器皆可，也是没有其他内置循环适用时所有探索赛季萨满祭司的默认循环；综合 模拟器 第 6 阶段、Icy Veins 和 Wowhead。以烈焰震击拉怪；用地震术打断。三个或更多敌人时：熔岩图腾，在火焰图腾旁使用火焰新星，漩涡武器达到四层时使用闪电链，烈焰震击。然后漩涡武器达到五层时使用熔岩爆裂，风暴打击，熔岩猛击，五层时使用闪电箭，烈焰震击能持续时使用烈焰震击，地震术，熔火爆裂，目标不在攻击范围内时使用闪电箭。提醒：风怒武器（学会前为石化武器），有熔岩猛击时副手武器使用火舌武器（否则风怒武器；绝不用于盾牌；Icy Veins 的双手都用风怒武器的步骤列为关闭状态），水之护盾或闪电之盾，头狼之魂，野性狼魂，法力值低于 65% 时使用萨满之怒，图腾，先祖指引。图腾投射、驱散和净化术由你自己掌控。"
L["rm.sod.shaman.restoration.Name"] = "恢复（探索赛季）"
L["rm.sod.shaman.restoration.Description"] = "探索赛季的恢复，10 级起（大部分天赋点在恢复）；综合 Icy Veins 和 Wowhead。对你的友方目标：低于 40% 时先激流再次级治疗波，消毒术或祛病术，你附近有三名队友低于 85% 时使用治疗之雨，有两名时使用治疗链（能量涌动触发时立即使用），低于 95% 时为潮汐奔涌使用激流，低于 90% 时使用治疗波。目标为敌人时会进行战斗。提醒：水之护盾（学会前为闪电之盾）、对你的友方目标或你自己施放大地之盾、萨满之怒、法力之潮图腾、法力之泉图腾和大地之力图腾。治疗谁以及战栗图腾或清除类图腾由你自己掌控。"
L["rm.sod.shaman.tank.Name"] = "坦克（探索赛季，土之道）"
L["rm.sod.shaman.tank.Description"] = "探索赛季的坦克，铭刻了土之道后选用；综合 Icy Veins、Wowhead、模拟器 和 Warcraft Tavern。以烈焰震击拉怪。地震术用于嘲讽近战范围内没有攻击你的目标，以及打断。两个或更多敌人时：熔火爆裂，烈焰震击，漩涡武器达到五层或能量涌动触发时使用闪电链，五层时使用火焰新星。然后保持烈焰震击，能量涌动触发时或烈焰震击持续期间使用熔岩爆裂，风暴打击，地震术，五层时使用闪电箭，熔火爆裂，冰霜震击。提醒：石化武器、闪电之盾、对自己施放头狼之魂、野性狼魂、萨满之怒、灼热图腾或熔岩图腾，以及队伍图腾。"
L["rm.tbc.shaman.elemental.icyveins.Name"] = "元素（Icy Veins & 模拟器）"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "元素天赋树的施法型元素。闪电箭作为填充技能；闪电链在元素掌握期间、法力值不低于 40% 时的节能施法期间，或法力值高于 80% 时随意施放；仅在移动时使用烈焰震击；地震术用于打断；成群敌人时使用火焰新星、闪电链和熔岩图腾。在闪电链之前，若目标处于近战范围内，则交给自动攻击处理以节省法力值。提醒：水之护盾或闪电之盾、武器灌注、天怒图腾（长时间战斗则用灼热图腾）、空气之怒图腾、法力之泉图腾、战斗后的图腾召唤、元素掌握以及嗜血/英勇。"
L["rm.tbc.shaman.elemental.nextaction.Name"] = "元素（NextActionTBC）"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "NextActionTBC 的元素，是推荐的 Icy Veins 元素内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。保持目标身上的烈焰震击，仅在面对两个或更多敌人且法力值高于 30% 时使用闪电链，否则使用闪电箭。会提醒你闪电之盾、武器灌注、元素掌握以及嗜血/英勇；图腾由你手动处理。"
L["rm.tbc.shaman.elemental.wowhead.Name"] = "元素（Wowhead）"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "Wowhead 的元素，是推荐的 Icy Veins 元素内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。70 级时闪电链冷却完毕即施放，其间穿插闪电箭（升级期间仅在元素掌握或节能施法时施放闪电链），仅在移动时使用烈焰震击，用地震术收掉会在施法完成前死亡的目标。图腾、护盾和冷却技能提醒与 Icy Veins 版本相同。"
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "增强（Icy Veins）"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "增强近战，适用于 1 至 70 级，也是没有其他内置循环适用时所有萨满祭司的默认循环。从远处用闪电箭拉怪，用地震术打断，附近有三个或更多敌人时放下火焰新星图腾和熔岩图腾，然后是风暴打击、风暴打击的减益效果存在时使用地震术、对能存活较久的目标使用烈焰震击、冷却完毕即用地震术，以及目标不在攻击范围内时使用闪电箭。独立提醒：武器灌注、水之护盾或闪电之盾、大地之力图腾、风怒图腾（组队）或风之优雅图腾（单刷）、长时间战斗中的灼热图腾、水系图腾、萨满之怒、首领战中的嗜血/英勇、单刷时的石爪图腾和土元素图腾。火元素图腾是默认关闭的可选步骤。图腾摆放、幽魂之狼和治疗由你自己掌控。"
L["rm.tbc.shaman.enhancement.simulator.Name"] = "增强（Wowhead & 模拟器）"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "70 级团队副本的图腾轮换模型，是推荐的 Icy Veins 增强内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。风暴打击、穿插火焰新星图腾、烈焰震击一旦消失就重新施放、以地震术作为主要震击术，仅在目标超出攻击范围时使用闪电箭。提醒会轮换风怒图腾和风之优雅图腾，保持灼热图腾，法力值不足时使用萨满之怒，并与 Icy Veins 版本共用武器灌注、护盾和图腾维护提醒。"
L["rm.tbc.shaman.restoration.Name"] = "恢复"
L["rm.tbc.shaman.restoration.Description"] = "恢复天赋树的治疗，作用于你的友方目标（没有目标时作用于你自己）：紧急情况下使用自然迅捷配合治疗波或次级治疗波，消毒术和祛病术，对你的焦点目标施放大地之盾，附近有三名盟友受伤时使用治疗链，否则使用治疗波。目标为敌对时切换为烈焰震击和闪电箭，用于单刷。提醒：水之护盾、对焦点目标施放大地之盾（请将坦克设为焦点目标）、法力之潮图腾、组队时的法力之泉图腾和大地之力图腾、嗜血/英勇。治疗谁以及使用哪个等级由你决定。"
